func bootstrapTestExperiment(t *testing.T, location string) string {
	config := transport_tpg.BootstrapConfig(t)
	if config == nil {
		return ""
	}
	project := envvar.GetTestProjectFromEnv()
	contextId := "tf-bootstrap-custom-job-exp"
	baseUrl := strings.ReplaceAll(transport_tpg.BaseUrl(vertexai.Product, config), "{{region}}", location)

	getUrl := fmt.Sprintf("%sprojects/%s/locations/%s/metadataStores/default/contexts/%s", baseUrl, project, location, contextId)
	res, err := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
		Config:    config,
		Method:    "GET",
		Project:   project,
		RawURL:    getUrl,
		UserAgent: config.UserAgent,
	})
	if err == nil {
		if name, ok := res["name"].(string); ok && name != "" {
			return name
		}
	}
	if !transport_tpg.IsGoogleApiErrorWithCode(err, 404) {
		t.Fatalf("Error getting bootstrap experiment %q: %s", contextId, err)
	}

	// Ensure default metadataStore exists.
	msGetUrl := fmt.Sprintf("%sprojects/%s/locations/%s/metadataStores/default", baseUrl, project, location)
	_, msErr := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
		Config:    config,
		Method:    "GET",
		Project:   project,
		RawURL:    msGetUrl,
		UserAgent: config.UserAgent,
	})
	if msErr != nil {
		if !transport_tpg.IsGoogleApiErrorWithCode(msErr, 404) {
			t.Fatalf("Error getting default metadataStore: %s", msErr)
		}
		msCreateUrl := fmt.Sprintf("%sprojects/%s/locations/%s/metadataStores?metadataStoreId=default", baseUrl, project, location)
		opRes, createMsErr := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
			Config:    config,
			Method:    "POST",
			Project:   project,
			RawURL:    msCreateUrl,
			UserAgent: config.UserAgent,
			Body:      map[string]interface{}{},
		})
		if createMsErr != nil {
			t.Fatalf("Error creating default metadataStore: %s", createMsErr)
		}
		var opResponse map[string]interface{}
		if waitErr := vertexai.VertexAIOperationWaitTimeWithResponse(config, opRes, &opResponse, project, location, "Creating default metadataStore", config.UserAgent, 10*time.Minute); waitErr != nil {
			t.Fatalf("Error waiting for default metadataStore creation: %s", waitErr)
		}
	}

	createUrl := fmt.Sprintf("%sprojects/%s/locations/%s/metadataStores/default/contexts?contextId=%s", baseUrl, project, location, contextId)
	createBody := map[string]interface{}{
		"displayName":   contextId,
		"schemaTitle":   "system.Experiment",
		"schemaVersion": "0.0.1",
	}
	createRes, err := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
		Config:    config,
		Method:    "POST",
		Project:   project,
		RawURL:    createUrl,
		UserAgent: config.UserAgent,
		Body:      createBody,
	})
	if err != nil {
		t.Fatalf("Error creating bootstrap experiment %q: %s", contextId, err)
	}
	name, _ := createRes["name"].(string)
	if name == "" {
		t.Fatalf("Bootstrap experiment %q returned empty name", contextId)
	}
	return name
}

func bootstrapTestExperimentRun(t *testing.T, location string) string {
	config := transport_tpg.BootstrapConfig(t)
	if config == nil {
		return ""
	}
	expName := bootstrapTestExperiment(t, location)
	if expName == "" {
		return ""
	}
	project := envvar.GetTestProjectFromEnv()
	contextId := "tf-bootstrap-custom-job-exp-run"
	baseUrl := strings.ReplaceAll(transport_tpg.BaseUrl(vertexai.Product, config), "{{region}}", location)

	getUrl := fmt.Sprintf("%sprojects/%s/locations/%s/metadataStores/default/contexts/%s", baseUrl, project, location, contextId)
	res, err := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
		Config:    config,
		Method:    "GET",
		Project:   project,
		RawURL:    getUrl,
		UserAgent: config.UserAgent,
	})
	var name string
	hasParent := false
	if err == nil {
		name, _ = res["name"].(string)
		if parents, ok := res["parentContexts"].([]interface{}); ok {
			for _, p := range parents {
				if ps, ok := p.(string); ok && ps == expName {
					hasParent = true
					break
				}
			}
		}
	} else if !transport_tpg.IsGoogleApiErrorWithCode(err, 404) {
		t.Fatalf("Error getting bootstrap experiment run %q: %s", contextId, err)
	}

	if name == "" {
		createUrl := fmt.Sprintf("%sprojects/%s/locations/%s/metadataStores/default/contexts?contextId=%s", baseUrl, project, location, contextId)
		createBody := map[string]interface{}{
			"displayName":   contextId,
			"schemaTitle":   "system.ExperimentRun",
			"schemaVersion": "0.0.1",
		}
		createRes, createErr := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
			Config:    config,
			Method:    "POST",
			Project:   project,
			RawURL:    createUrl,
			UserAgent: config.UserAgent,
			Body:      createBody,
		})
		if createErr != nil {
			t.Fatalf("Error creating bootstrap experiment run %q: %s", contextId, createErr)
		}
		name, _ = createRes["name"].(string)
		if name == "" {
			t.Fatalf("Bootstrap experiment run %q returned empty name", contextId)
		}
	}

	if !hasParent {
		addChildrenUrl := fmt.Sprintf("%s%s:addContextChildren", baseUrl, expName)
		addChildrenBody := map[string]interface{}{
			"childContexts": []interface{}{name},
		}
		_, addErr := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
			Config:    config,
			Method:    "POST",
			Project:   project,
			RawURL:    addChildrenUrl,
			UserAgent: config.UserAgent,
			Body:      addChildrenBody,
		})
		if addErr != nil {
			t.Fatalf("Error linking bootstrap experiment run %q to experiment %q: %s", name, expName, addErr)
		}
	}
	return name
}

func bootstrapTestPersistentResourceId(t *testing.T, location string) string {
	config := transport_tpg.BootstrapConfig(t)
	if config == nil {
		return ""
	}
	project := envvar.GetTestProjectFromEnv()
	prId := "tf-bootstrap-custom-job-pr"
	baseUrl := strings.ReplaceAll(transport_tpg.BaseUrl(vertexai.Product, config), "{{region}}", location)
	getUrl := fmt.Sprintf("%sprojects/%s/locations/%s/persistentResources/%s", baseUrl, project, location, prId)

	res, err := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
		Config:    config,
		Method:    "GET",
		Project:   project,
		RawURL:    getUrl,
		UserAgent: config.UserAgent,
	})
	if err == nil {
		state, _ := res["state"].(string)
		switch state {
		case "RUNNING":
			return prId
		case "PROVISIONING":
			deadline := time.Now().Add(30 * time.Minute)
			for time.Now().Before(deadline) {
				time.Sleep(20 * time.Second)
				pollRes, pollErr := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
					Config:    config,
					Method:    "GET",
					Project:   project,
					RawURL:    getUrl,
					UserAgent: config.UserAgent,
				})
				if pollErr != nil {
					t.Fatalf("Error polling bootstrap persistent resource %q: %s", prId, pollErr)
				}
				pollState, _ := pollRes["state"].(string)
				if pollState == "RUNNING" {
					return prId
				}
				if pollState != "PROVISIONING" {
					t.Fatalf("Bootstrap persistent resource %q entered unexpected state %q", prId, pollState)
				}
			}
			t.Fatalf("Timed out waiting for bootstrap persistent resource %q to reach RUNNING", prId)
		default:
			delOp, delErr := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
				Config:    config,
				Method:    "DELETE",
				Project:   project,
				RawURL:    getUrl,
				UserAgent: config.UserAgent,
			})
			if delErr != nil && !transport_tpg.IsGoogleApiErrorWithCode(delErr, 404) {
				t.Fatalf("Error deleting unhealthy bootstrap persistent resource %q: %s", prId, delErr)
			}
			if delErr == nil {
				var delResp map[string]interface{}
				_ = vertexai.VertexAIOperationWaitTimeWithResponse(config, delOp, &delResp, project, location, "Deleting unhealthy bootstrap persistent resource", config.UserAgent, 20*time.Minute)
			}
		}
	} else if !transport_tpg.IsGoogleApiErrorWithCode(err, 404) {
		t.Fatalf("Error getting bootstrap persistent resource %q: %s", prId, err)
	}

	createUrl := fmt.Sprintf("%sprojects/%s/locations/%s/persistentResources?persistentResourceId=%s", baseUrl, project, location, prId)
	createBody := map[string]interface{}{
		"resourcePools": []interface{}{
			map[string]interface{}{
				"machineSpec": map[string]interface{}{
					"machineType": "e2-standard-4",
				},
				"replicaCount": 1,
			},
		},
	}
	opRes, err := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
		Config:    config,
		Method:    "POST",
		Project:   project,
		RawURL:    createUrl,
		UserAgent: config.UserAgent,
		Body:      createBody,
	})
	if err != nil {
		t.Fatalf("Error creating bootstrap persistent resource %q: %s", prId, err)
	}
	var opResponse map[string]interface{}
	if err := vertexai.VertexAIOperationWaitTimeWithResponse(config, opRes, &opResponse, project, location, "Creating bootstrap persistent resource", config.UserAgent, 30*time.Minute); err != nil {
		t.Fatalf("Error waiting for bootstrap persistent resource %q creation: %s", prId, err)
	}
	return prId
}

