func testAccVertexAICustomJob_explicitExperimentEnv(context map[string]interface{}) string {
	return acctest.Nprintf(`
resource "google_vertex_ai_custom_job" "custom_job" {
  display_name = "%{display_name}"
  region       = "us-central1"

  job_spec {
    worker_pool_specs {
      replica_count = 1

      machine_spec {
        machine_type = "n1-standard-4"
      }

      disk_spec {
        boot_disk_type    = "pd-ssd"
        boot_disk_size_gb = 100
      }

      container_spec {
        image_uri = "us-docker.pkg.dev/vertex-ai/training/tf-cpu.2-12.py310:latest"
        command   = ["echo", "test"]

        env {
          name  = "AIP_EXPERIMENT_NAME"
          value = "manual-exp"
        }

        env {
          name  = "AIP_EXPERIMENT_RUN_NAME"
          value = "manual-run"
        }
      }
    }
  }
}
`, context)
}
